    [9, 9, 9, 9, 9, 9, 9, 9, 9],
    [9, 9, 9, 9, 9, 9, 9, 9, 9]
]

def dominant_non_bg(block, exclude=9):
    colors_having = []
    for row in block:
        for cell in row:
            if cell != exclude:
                colors_having.append(cell)
    if not colors_having:
        return exclude  # all background
    return max(set(colors_having), key=lambda c: colors_having.count(c))

